export const discountedReturn=(rewards,gamma)=>rewards.reduce((sum,r,i)=>sum+gamma**i*r,0);
export const tdTarget=(reward,gamma,nextValue,terminated)=>reward+(terminated?0:gamma*nextValue);
export const qUpdate=(q,reward,gamma,nextQ,alpha,terminated=false)=>q+alpha*(tdTarget(reward,gamma,nextQ,terminated)-q);
export const epsilonPolicy=(values,epsilon)=>{const max=Math.max(...values),best=values.flatMap((v,i)=>v===max?[i]:[]);return values.map((_,i)=>epsilon/values.length+(best.includes(i)?(1-epsilon)/best.length:0))};
export const grid={size:4,start:12,goal:3,pits:[7,11],walls:[5,9],actions:['↑','→','↓','←']};
export function transition(s,a){if(s===grid.goal||grid.pits.includes(s))return {next:s,reward:0,terminated:true};const [dr,dc]=[[-1,0],[0,1],[1,0],[0,-1]][a],r=Math.floor(s/4)+dr,c=s%4+dc;let next=r<0||r>=4||c<0||c>=4?s:r*4+c;if(grid.walls.includes(next))next=s;const terminated=next===grid.goal||grid.pits.includes(next),reward=next===grid.goal?1:grid.pits.includes(next)?-1:-.04;return {next,reward,terminated}}
export function createQLearner(){return {q:Array.from({length:16},()=>[0,0,0,0]),episodes:0,successes:0,returns:[],lastPath:[grid.start],rng:42,lastTransition:null}}
function random(state){state.rng=(Math.imul(1664525,state.rng)+1013904223)>>>0;return state.rng/4294967296}
export function trainEpisode(state,{epsilon=.25,alpha=.3,gamma=.9}={}){let s=grid.start,total=0,path=[s];for(let t=0;t<80;t++){const values=state.q[s],max=Math.max(...values),best=values.flatMap((v,i)=>v===max?[i]:[]),a=random(state)<epsilon?Math.floor(random(state)*4):best[Math.floor(random(state)*best.length)],tr=transition(s,a),old=state.q[s][a],target=tdTarget(tr.reward,gamma,Math.max(...state.q[tr.next]),tr.terminated);state.q[s][a]=qUpdate(old,tr.reward,gamma,Math.max(...state.q[tr.next]),alpha,tr.terminated);state.lastTransition={s,a,...tr,old,target,updated:state.q[s][a]};total+=tr.reward;s=tr.next;path.push(s);if(tr.terminated){if(s===grid.goal)state.successes++;break}}state.episodes++;state.returns.push(total);state.lastPath=path;return state}
export function evaluateGreedy(state){let s=grid.start,total=0,path=[s];for(let t=0;t<40;t++){const a=state.q[s].indexOf(Math.max(...state.q[s])),tr=transition(s,a);s=tr.next;path.push(s);total+=tr.reward;if(tr.terminated)return {success:s===grid.goal,total,path};}return {success:false,total,path}}
export const replayExample=Array.from({length:8},(_,i)=>{const s=[12,8,4,0,1,2,6,10][i],a=[0,0,0,1,1,1,0,1][i];return {s,a,...transition(s,a)}});
export function sampleIndices(seed,count=3){const ids=Array.from({length:8},(_,i)=>i);let v=seed>>>0;for(let i=7;i>0;i--){v=(Math.imul(1664525,v)+1013904223)>>>0;const j=v%(i+1);[ids[i],ids[j]]=[ids[j],ids[i]]}return ids.slice(0,count)}
